import re, sys, pathlib
S=pathlib.Path("/Users/kristinarash/DEV/Flint/staging/library/strength-and-conditioning/supertraining--verkhoshansky")
V=pathlib.Path("/Users/kristinarash/SecondBrain/Knowledge/library/strength-and-conditioning/supertraining--verkhoshansky")
LINK=re.compile(r"\[\[([^\]|#\n]+)")
apply = "--apply" in sys.argv
def links(s): return set(LINK.findall(s))
def key(s): return s.strip()[:40]
report=[]; written=0
for f in sorted(S.glob("*.md")):
    v=V/f.name
    if not v.exists() or f.name=="_book.md": continue
    if f.read_bytes()==v.read_bytes(): continue
    SL=f.read_text(encoding="utf-8").split("\n")
    VL=v.read_text(encoding="utf-8").split("\n")
    Sset=set(SL); Vset=set(VL)
    consumed=set(); out=[]; anchors={}
    for L in VL:
        if L in Sset or not L.strip():
            out.append(L); continue
        cands=[M for M in SL if M not in Vset and key(M)==key(L) and M not in consumed and M.strip()]
        if cands:
            M=cands[0]; consumed.add(M)
            vl, ml = links(L), links(M)
            if ml>=vl and ml!=vl:
                out.append(M); continue
            extra=[x for x in re.findall(r"\[\[[^\]]+\]\]", M) if x[2:-2] not in vl]
            if extra and M.strip().startswith("**Related**") and L.strip().startswith("**Related**"):
                out.append(L.rstrip()+"; "+"; ".join(extra)); continue
            out.append(L); continue
        out.append(L)
    # insert staging-only lines after their nearest staging anchor
    outset=set(out)
    last_anchor=None
    insert_after={}
    prev=None
    for N in SL:
        if N in Vset or N in consumed or not N.strip():
            if N in outset: prev=N
            continue
        insert_after.setdefault(prev, []).append(N)
    final=[]
    for line in ([None]+out):
        if line is not None: final.append(line)
        for N in insert_after.get(line, []): final.append(N)
    text="\n".join(final)
    lost=links("\n".join(VL))-links(text)
    missing=links("\n".join(SL))-links(text)
    inserted=sum(len(x) for x in insert_after.values())
    report.append((f.name, inserted, len(consumed), sorted(lost), sorted(missing)))
    if apply:
        v.write_text(text, encoding="utf-8"); written+=1
bad=[r for r in report if r[3]]
print("files considered:", len(report), "| files with vault links LOST:", len(bad))
print("files with staging links still missing:", sum(1 for r in report if r[4]))
print("staging-only lines inserted:", sum(r[1] for r in report))
for r in bad[:10]: print("LOST", r[0], r[3][:3])
for r in report:
    if r[4]: print("MISSING", r[0], r[4][:3])
if apply: print("written:", written)
PY
cd "$TMPDIR/merge" && python3 backlink_merge.py 2>&1 | head -60

